import{_ as s,o as i,c as n,a6 as o}from"./chunks/framework.BBdhcoHf.js";const g=JSON.parse('{"title":"ADR-014: Peer SDK Session Signal Handling","description":"","frontmatter":{},"headers":[],"relativePath":"adr/014-peer-session-signals.md","filePath":"adr/014-peer-session-signals.md","lastUpdated":1772916561000}'),a={name:"adr/014-peer-session-signals.md"};function t(d,e,r,c,l,p){return i(),n("div",null,[...e[0]||(e[0]=[o(`<div style="display:none;" hidden="true" aria-hidden="true">Are you an LLM? You can read better optimized documentation at /adr/014-peer-session-signals.md for this page in Markdown format</div><h1 id="adr-014-peer-sdk-session-signal-handling" tabindex="-1">ADR-014: Peer SDK Session Signal Handling <a class="header-anchor" href="#adr-014-peer-sdk-session-signal-handling" aria-label="Permalink to “ADR-014: Peer SDK Session Signal Handling”">​</a></h1><ul><li><strong>Date</strong>: 2026-02-25</li><li><strong>Status</strong>: Accepted</li><li><strong>Affects</strong>: SDK, Runtime</li></ul><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to “Context”">​</a></h2><p>SBRP relay sessions can be paused mid-flight when the relay daemon loses its upstream connection. The protocol emits control signals (<code>session_paused</code>, <code>session_resumed</code>, <code>session_ended</code>, <code>session_pending</code>) to drive lifecycle transitions. The Peer SDK must surface these to application code without leaking relay internals.</p><p>Three design problems arise:</p><ol><li><strong>How do signals cross the negotiator boundary?</strong> Negotiators are stateless factories; adding an event emitter to the <code>Negotiator</code> interface would couple the runtime to specific protocols.</li><li><strong>What is <code>paused</code> from the SDK consumer&#39;s perspective?</strong> Is it a distinct state or an implementation detail of the connection layer?</li><li><strong>What does <code>session_ended</code> mean, and does it differ between client and server peers?</strong></li></ol><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to “Decision”">​</a></h2><h3 id="_1-signal-propagation-via-subscribesignals-on-negotiationresult" tabindex="-1">1. Signal propagation via <code>subscribeSignals</code> on <code>NegotiationResult</code> <a class="header-anchor" href="#_1-signal-propagation-via-subscribesignals-on-negotiationresult" aria-label="Permalink to “1. Signal propagation via subscribeSignals on NegotiationResult”">​</a></h3><div class="language-ts"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">interface</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> NegotiationResult</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  // ...</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">  subscribeSignals</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">?:</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">handler</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">signal</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> SessionSignal</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> void</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> () </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> void</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>Returning an unsubscribe function gives the SDK precise lifecycle control: on each <code>negotiate()</code> call, <code>PeerImpl</code> intercepts <code>subscribeSignals</code>, wires the handler, and tears it down on session close or reconnect — re-subscribing fresh on retry. A callback option on <code>Negotiator</code> was rejected because it gives no mechanism to swap handlers across reconnects.</p><h3 id="_2-paused-as-a-first-class-peer-state" tabindex="-1">2. <code>paused</code> as a first-class Peer state <a class="header-anchor" href="#_2-paused-as-a-first-class-peer-state" aria-label="Permalink to “2. paused as a first-class Peer state”">​</a></h3><p><code>paused</code> is visible in the public <code>PeerState</code> union. Hiding it would force consumers to infer pause indirectly from failed sends, which is worse DX and harder to reason about.</p><p><strong>Behavior during <code>paused</code>:</strong></p><table tabindex="0"><thead><tr><th>Operation</th><th>Behavior</th></tr></thead><tbody><tr><td><code>sendRaw()</code></td><td>Rejects immediately with <code>PeerError(&quot;session_paused&quot;)</code></td></tr><tr><td>RPC calls</td><td>Policy-dependent: reject if <code>onDisconnect: &quot;fail&quot;</code>, queue if <code>&quot;pause&quot;</code></td></tr><tr><td>Event publishes</td><td>Always buffered; flushed on <code>session_resumed</code></td></tr></tbody></table><p><code>sendRaw</code> rejects because it bypasses the SDK&#39;s queuing layer — callers own flow control. Events always buffer because dropping them during pause is silent data loss. RPC queuing is opt-in (<code>connectionPolicy.onDisconnect: &quot;pause&quot;</code>) because callers must acknowledge the memory trade-off.</p><p><strong>Event emission:</strong></p><ul><li><code>sessionPaused</code> fires on entering <code>paused</code>.</li><li><code>sessionResumed</code> fires on returning to <code>active</code> from <code>paused</code>.</li><li><code>connected</code> does NOT re-fire on resume — only on a fresh connection (non-<code>paused</code> → <code>active</code>).</li><li><code>disconnected</code> fires whenever the peer leaves <code>{active, paused}</code> for any other state.</li></ul><h3 id="_3-session-ended-semantics-differ-by-peer-role" tabindex="-1">3. <code>session_ended</code> semantics differ by peer role <a class="header-anchor" href="#_3-session-ended-semantics-differ-by-peer-role" aria-label="Permalink to “3. session_ended semantics differ by peer role”">​</a></h3><p><code>session_ended</code> means the remote client left the relay; the link to the daemon remains open.</p><p><strong>Client peer (<code>createPeer</code>):</strong> terminate the current session; let the retry policy decide whether to reconnect. Calling <code>disconnect()</code> would move permanently to <code>closed</code> — wrong, because the signal does not mean &quot;this peer is gone forever&quot;.</p><p><strong>Accepted peer (<code>listen</code>):</strong> call <code>disconnect()</code> directly. Accepted peers have no retry semantics and exist only for the duration of an inbound connection.</p><h3 id="_4-session-pending-is-a-no-op" tabindex="-1">4. <code>session_pending</code> is a no-op <a class="header-anchor" href="#_4-session-pending-is-a-no-op" aria-label="Permalink to “4. session_pending is a no-op”">​</a></h3><p><code>session_pending</code> means the daemon reconnected to the relay but has not confirmed readiness. It triggers no state transition; if currently <code>paused</code>, peers remain <code>paused</code>. Only <code>session_resumed</code> returns the peer to <code>active</code>.</p><h2 id="invariants" tabindex="-1">Invariants <a class="header-anchor" href="#invariants" aria-label="Permalink to “Invariants”">​</a></h2><ul><li>Signals are processed only from <code>active</code> or <code>paused</code>; signals during <code>connecting</code>, <code>negotiating</code>, or <code>reconnecting</code> are dropped.</li><li><code>subscribeSignals</code> unsubscribe MUST be called before establishing a new subscription (enforced by <code>runLoop</code>).</li><li>Client peers (<code>PeerImpl</code>) MUST NOT call <code>disconnect()</code> on <code>session_ended</code> — session termination must go through the session manager so the retry policy applies.</li></ul><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to “Consequences”">​</a></h2><ul><li>Control signals (SBRP) remain invisible to the runtime core; <code>SessionSignal</code> is a generic type with no protocol-specific fields.</li><li>Consumers observe a clean <code>paused</code> → <code>active</code> round-trip with automatic event and optional RPC resume — no manual retry plumbing needed.</li><li>Non-SBRP negotiators returning no <code>subscribeSignals</code> are unaffected; <code>paused</code> is never entered.</li></ul><h2 id="references" tabindex="-1">References <a class="header-anchor" href="#references" aria-label="Permalink to “References”">​</a></h2><ul><li>ADR-009: Runtime Session Lifecycle</li><li>ADR-013: Peer SDK Core Design Decisions</li><li><code>packages/runtime/src/session/types.ts</code> — <code>NegotiationResult</code>, <code>SessionSignal</code></li><li><code>packages/peer/src/peer.ts</code> — <code>handleSessionSignal</code>, <code>transition</code></li><li><code>packages/peer/src/listen.ts</code> — <code>ConnectedPeerImpl.handleSessionSignal</code></li></ul>`,30)])])}const u=s(a,[["render",t]]);export{g as __pageData,u as default};
